// ─────────────────────────────────────────────────────────────────────────
//  01 · half-even vs half-up on negative money                       ★★☆
//  concepts: exact decimal rounding · half-even vs half-up · sign symmetry
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.math.*;

class Exercise {
    enum Mode { HALF_EVEN, HALF_UP }

    // TODO: fix — this is the shipped helper. It ignores the mode, rounds a
    // double, and refunds no longer mirror charges.
    /** Mills (1/10 cent) to whole cents; HALF_UP means half away from zero. */
    static long toCents(long mills, Mode mode) {
        return Math.round(mills / 10.0);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("half-even sends an exact half cent to the even neighbour", () -> {
            eq(toCents(12345, Mode.HALF_EVEN), 1234);
            eq(toCents(12355, Mode.HALF_EVEN), 1236);
        });
        test("past the half always rounds up", () ->
            eq(toCents(12346, Mode.HALF_EVEN), 1235));
        test("negative halves go to the even neighbour too", () -> {
            eq(toCents(-12345, Mode.HALF_EVEN), -1234);
            eq(toCents(-12355, Mode.HALF_EVEN), -1236);
        });
        test("small halves: 0.5, 1.5 and 2.5 cents", () -> {
            eq(toCents(5, Mode.HALF_EVEN), 0);
            eq(toCents(15, Mode.HALF_EVEN), 2);
            eq(toCents(25, Mode.HALF_EVEN), 2);
        });
        test("half-up rounds a positive half away from zero", () ->
            eq(toCents(12345, Mode.HALF_UP), 1235));
        test("half-up on a negative refund goes further negative", () ->
            eq(toCents(-12345, Mode.HALF_UP), -1235));
        test("half-up moves only exact halves away from zero (boundary)", () -> {
            eq(toCents(12344, Mode.HALF_UP), 1234);
            eq(toCents(-12346, Mode.HALF_UP), -1235);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

