class Exercise {
    enum Mode { HALF_EVEN, HALF_UP }

    /** Mills (1/10 cent) to whole cents; HALF_UP means half away from zero. */
    static long toCents(long mills, Mode mode) {
        RoundingMode rm = mode == Mode.HALF_EVEN ? RoundingMode.HALF_EVEN : RoundingMode.HALF_UP;
        return BigDecimal.valueOf(mills, 1).setScale(0, rm).longValueExact();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("half-even sends an exact half cent to the even neighbour", () -> {
