            eq(toCents(12346, Mode.HALF_EVEN), 1235));
        test("negative halves go to the even neighbour too", () -> {
            eq(toCents(-12345, Mode.HALF_EVEN), -1234);
            eq(toCents(-12355, Mode.HALF_EVEN), -1236);
        });
        test("small halves: 0.5, 1.5 and 2.5 cents", () -> {
            eq(toCents(5, Mode.HALF_EVEN), 0);
            eq(toCents(15, Mode.HALF_EVEN), 2);
            eq(toCents(25, Mode.HALF_EVEN), 2);
        });
        test("half-up rounds a positive half away from zero", () ->
            eq(toCents(12345, Mode.HALF_UP), 1235));
