// ─────────────────────────────────────────────────────────────────────────
//  07 · the reading that never equals itself                         ★★☆
//  concepts: NaN never equals itself · negative zero · Double.equals vs == · sort order of doubles
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** True for a missing reading, which the sensor feed encodes as NaN. */
    static boolean isMissing(double reading) {
        return Double.isNaN(reading);
    }

    /** The reading to use as a grouping key: -0.0 becomes 0.0, everything else (NaN included) is unchanged. */
    static double canonical(double reading) {
        return reading == 0.0 ? 0.0 : reading;
    }

    /** How many distinct readings there are, with -0.0 and 0.0 the same reading and every NaN one missing value. */
    static int distinctReadings(List<Double> readings) {
        var seen = new HashSet<Double>();
        for (double r : readings) seen.add(canonical(r));
        return seen.size();
    }

    /** The readings in ascending order, -0.0 before 0.0 and NaN last. */
    static List<Double> ascending(List<Double> readings) {
        var copy = new ArrayList<>(readings);
        copy.sort(Double::compare);
        return copy;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("NaN is missing although it never equals itself", () -> {
            double nan = Double.NaN;
            ok(nan != nan, "IEEE: NaN is unequal even to itself");
            ok(isMissing(nan), "NaN is the missing marker");
            ok(!isMissing(0.0), "zero is a real reading");
        });
        test("a computed NaN is missing too", () -> {
            ok(isMissing(0.0 / 0.0), "0/0 is NaN");
            ok(isMissing(Math.sqrt(-1)), "sqrt(-1) is NaN");
        });
        test("negative zero becomes plain zero, other readings stay", () -> {
            eq(String.valueOf(canonical(-0.0)), "0.0");
            eq(String.valueOf(canonical(-2.5)), "-2.5");
            ok(Double.isNaN(canonical(Double.NaN)), "NaN stays NaN");
        });
        test("a reading rounded to -0.0 groups with zero", () ->
            eq(distinctReadings(List.of(0.0, -0.0, 1.5, 1.5)), 2));
        test("every missing reading counts once", () ->
            eq(distinctReadings(List.of(Double.NaN, 0.0 / 0.0, 1.0)), 2));
        test("ascending puts negative zero before zero and NaN last", () ->
            eq(ascending(List.of(Double.NaN, 1.0, 0.0, -0.0, -1.0)).toString(), "[-1.0, -0.0, 0.0, 1.0, NaN]"));
        test("no readings (boundary)", () -> {
            eq(distinctReadings(List.of()), 0);
            eq(ascending(List.of()), List.of());
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

