//  08 · truncate to a byte budget                                    ★★☆
//  concepts: UTF-8 byte length · code points · truncating without splitting a character
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.nio.charset.StandardCharsets;
import java.util.*;

class Exercise {

    /** The number of bytes in s's UTF-8 encoding. */
    static int utf8Length(String s) {
        throw new UnsupportedOperationException("TODO: count encoded bytes, not chars");
    }

    /** The longest prefix of s whose UTF-8 encoding fits in maxBytes, never splitting a character. */
    static String truncateUtf8(String s, int maxBytes) {
        throw new UnsupportedOperationException("TODO: walk whole code points while they still fit");
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("utf8Length counts bytes, not chars", () -> {
            eq(utf8Length("hello"), 5);
            eq(utf8Length("caf\u00e9"), 5);
            eq(utf8Length("\u20ac"), 3);
            eq(utf8Length("a\uD83D\uDE42b"), 6);
            eq(utf8Length(""), 0);
        });
        test("ASCII truncates by count", () -> {
            eq(truncateUtf8("hello", 10), "hello");
            eq(truncateUtf8("hello", 3), "hel");
        });
        test("a two-byte character fits exactly or not at all (boundary)", () -> {
            eq(truncateUtf8("caf\u00e9", 5), "caf\u00e9");
            eq(truncateUtf8("caf\u00e9", 4), "caf");
        });
        test("a three-byte character is never cut", () -> {
            eq(truncateUtf8("\u20acuro", 2), "");
            eq(truncateUtf8("\u20acuro", 3), "\u20ac");
        });
        test("an emoji's four bytes stay together", () -> {
            eq(truncateUtf8("a\uD83D\uDE42b", 2), "a");
            eq(truncateUtf8("a\uD83D\uDE42b", 4), "a");
            eq(truncateUtf8("a\uD83D\uDE42b", 5), "a\uD83D\uDE42");
            eq(truncateUtf8("a\uD83D\uDE42b", 6), "a\uD83D\uDE42b");
        });
        test("a zero budget keeps nothing", () -> {
            eq(truncateUtf8("abc", 0), "");
            eq(truncateUtf8("", 0), "");
        });
        test("a negative budget is refused", () ->
            raises(IllegalArgumentException.class, () -> truncateUtf8("abc", -1)));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

exercises.solution:
// ─────────────────────────────────────────────────────────────────────────
//  08 · truncate to a byte budget                                    ★★☆
//  concepts: UTF-8 byte length · code points · truncating without splitting a character
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.nio.charset.StandardCharsets;
import java.util.*;

class Exercise {

    /** The number of bytes in s's UTF-8 encoding. */
    static int utf8Length(String s) {
        return s.getBytes(StandardCharsets.UTF_8).length;
    }

    /** The longest prefix of s whose UTF-8 encoding fits in maxBytes, never splitting a character. */
    static String truncateUtf8(String s, int maxBytes) {
        if (maxBytes < 0) throw new IllegalArgumentException("maxBytes must not be negative, was " + maxBytes);
        int bytes = 0;
        int end = 0;
        while (end < s.length()) {
            int cp = s.codePointAt(end);
            int size = cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
            if (bytes + size > maxBytes) break;
            bytes += size;
            end += Character.charCount(cp);
        }
        return s.substring(0, end);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("utf8Length counts bytes, not chars", () -> {
            eq(utf8Length("hello"), 5);
            eq(utf8Length("caf\u00e9"), 5);
            eq(utf8Length("\u20ac"), 3);
            eq(utf8Length("a\uD83D\uDE42b"), 6);
            eq(utf8Length(""), 0);
        });
        test("ASCII truncates by count", () -> {
            eq(truncateUtf8("hello", 10), "hello");
            eq(truncateUtf8("hello", 3), "hel");
        });
        test("a two-byte character fits exactly or not at all (boundary)", () -> {
            eq(truncateUtf8("caf\u00e9", 5), "caf\u00e9");
            eq(truncateUtf8("caf\u00e9", 4), "caf");
        });
        test("a three-byte character is never cut", () -> {
            eq(truncateUtf8("\u20acuro", 2), "");
            eq(truncateUtf8("\u20acuro", 3), "\u20ac");
        });
        test("an emoji's four bytes stay together", () -> {
            eq(truncateUtf8("a\uD83D\uDE42b", 2), "a");
            eq(truncateUtf8("a\uD83D\uDE42b", 4), "a");
            eq(truncateUtf8("a\uD83D\uDE42b", 5), "a\uD83D\uDE42");
            eq(truncateUtf8("a\uD83D\uDE42b", 6), "a\uD83D\uDE42b");
        });
        test("a zero budget keeps nothing", () -> {
            eq(truncateUtf8("abc", 0), "");
            eq(truncateUtf8("", 0), "");
        });
        test("a negative budget is refused", () ->
            raises(IllegalArgumentException.class, () -> truncateUtf8("abc", -1)));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}
